public struct FfiScanFlags {
    public var remoteAppRunning: Bool
    public var inCall: Bool
    public var bankAppOpen: Bool
    /**
     * JSON LearnedRuleSet (rỗng = không dùng luật học được).
     */
    public var learnedJson: String
    /**
     * JSON Blacklists {"domains":[],"phones":[],"accounts":[]} (rỗng = trống).
     */
    public var blacklistJson: String

    // Default memberwise initializers are never public by default, so we
    // declare one manually.
    public init(remoteAppRunning: Bool, inCall: Bool, bankAppOpen: Bool, 
        /**
         * JSON LearnedRuleSet (rỗng = không dùng luật học được).
         */learnedJson: String, 
        /**
         * JSON Blacklists {"domains":[],"phones":[],"accounts":[]} (rỗng = trống).
         */blacklistJson: String) {
        self.remoteAppRunning = remoteAppRunning
        self.inCall = inCall
        self.bankAppOpen = bankAppOpen
        self.learnedJson = learnedJson
        self.blacklistJson = blacklistJson
    }
}



extension FfiScanFlags: Equatable, Hashable {
    public static func ==(lhs: FfiScanFlags, rhs: FfiScanFlags) -> Bool {
        if lhs.remoteAppRunning != rhs.remoteAppRunning {
            return false
        }
        if lhs.inCall != rhs.inCall {
            return false
        }
        if lhs.bankAppOpen != rhs.bankAppOpen {
            return false
        }
        if lhs.learnedJson != rhs.learnedJson {
            return false
        }
        if lhs.blacklistJson != rhs.blacklistJson {
            return false
        }
        return true
    }

    public func hash(into hasher: inout Hasher) {
        hasher.combine(remoteAppRunning)
        hasher.combine(inCall)
        hasher.combine(bankAppOpen)
        hasher.combine(learnedJson)
        hasher.combine(blacklistJson)
    }
}


