/**
 * Tác vụ AI. Tên tránh đụng `Task` của Swift (binding sinh ra cùng module).
 */

public enum AiTaskKind {
    
    case summarize
    case translate
    case solve
    case analyze
}


#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeAiTaskKind: FfiConverterRustBuffer {
    typealias SwiftType = AiTaskKind

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> AiTaskKind {
        let variant: Int32 = try readInt(&buf)
        switch variant {
        
        case 1: return .summarize
        
        case 2: return .translate
        
        case 3: return .solve
        
        case 4: return .analyze
        
        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: AiTaskKind, into buf: inout [UInt8]) {
        switch value {
        
        
        case .summarize:
            writeInt(&buf, Int32(1))
        
        
        case .translate:
            writeInt(&buf, Int32(2))
        
        
        case .solve:
            writeInt(&buf, Int32(3))
        
        
        case .analyze:
            writeInt(&buf, Int32(4))
        
        }
    }
}


